// Normaliza los parámetros de entrada según el origen (Chat, Webhook o Manual)
const incoming = $input.first().json;

let prompt = "¿Qué servicios están corriendo en nuestro homelab y cómo puedes ayudarme?";
let systemPrompt = "Eres un asistente inteligente de Homelab. Responde en español de forma concisa, estructurada y precisa.";
let model = "qwen2.5:3b";
let temperature = 0.7;
let maxTokens = 300;
let keepAlive = "1h";
let source = "manual";

// Si viene de Webhook (POST body)
if (incoming.body) {
  prompt = incoming.body.prompt || incoming.body.question || incoming.body.message || prompt;
  systemPrompt = incoming.body.system || systemPrompt;
  model = incoming.body.model || model;
  temperature = incoming.body.temperature !== undefined ? incoming.body.temperature : temperature;
  maxTokens = incoming.body.max_tokens || incoming.body.num_predict || maxTokens;
  keepAlive = incoming.body.keep_alive || keepAlive;
  source = "webhook";
}
// Si viene del Chat Trigger de n8n
else if (incoming.chatInput) {
  prompt = incoming.chatInput;
  source = "chat";
}
// Si viene con un campo directo (ej. prompt o question en JSON manual)
else if (incoming.prompt || incoming.question) {
  prompt = incoming.prompt || incoming.question;
  systemPrompt = incoming.system || systemPrompt;
  model = incoming.model || model;
}

return [{
  json: {
    ollama_url: "http://192.168.0.118:11434/api/generate",
    source: source,
    requestPayload: {
      model: model,
      prompt: prompt,
      system: systemPrompt,
      stream: false,
      keep_alive: keepAlive,
      options: {
        temperature: temperature,
        num_predict: maxTokens
      }
    },
    startTime: new Date().toISOString()
  }
}];

const prepData = $('Prepare Prompt & Params').first().json;
const ollamaResponse = $input.first().json;

const totalDurationMs = ollamaResponse.total_duration ? (ollamaResponse.total_duration / 1e6).toFixed(2) : null;
const evalDurationMs = ollamaResponse.eval_duration ? (ollamaResponse.eval_duration / 1e6).toFixed(2) : null;
const evalCount = ollamaResponse.eval_count || 0;
const tokensPerSec = evalDurationMs && evalDurationMs > 0 ? ((evalCount / (evalDurationMs / 1000))).toFixed(1) : null;

const cleanOutput = {
  success: true,
  source: prepData.source,
  question: prepData.requestPayload.prompt,
  answer: ollamaResponse.response,
  model: ollamaResponse.model || prepData.requestPayload.model,
  created_at: ollamaResponse.created_at,
  metrics: {
    total_duration_ms: totalDurationMs,
    eval_tokens: evalCount,
    tokens_per_second: tokensPerSec
  }
};

return [{ json: cleanOutput }];
